namespace{bool tracking=false;uint64_t allocations=0;}
void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
int main(){try{using T=ks::NativeArpResetService;std::vector<uint8_t>m(1<<24);uint64_t graphs=0,phases=0,rejects=0,reads=0,writes=0;uint32_t components=0;
for(unsigned policy=0;policy<256;++policy)for(unsigned mode:{0u,1u,64u,65u})for(unsigned held=0;held<3;++held){std::fill(m.begin()+0x15000,m.begin()+0x30000,uint8_t(0));const unsigned part=policy%5;const auto base=0x160d2u+334*part;m[0x17526]=uint8_t(part);m[base+324]=uint8_t(mode);m[base+325]=uint8_t(policy);m[base+327]=uint8_t(policy);m[base+322]=93;m[base+323]=17;m[base+326]=99;m[base+308]=4;for(unsigned i=0;i<16;++i)m[base+208+i]=held?uint8_t(held==1?(i==15?128:0):255):0;
const unsigned length=1+policy%4;for(unsigned i=0;i<length;++i)m[0x19000+i]=uint8_t((policy&127)|(i+1<length?128:0));m[base+48]=0;m[base+49]=1;m[base+50]=0x90;m[base+51]=0;m[0x168fc+249]=uint8_t(policy%4);m[0x168fc+219]=uint8_t(policy);m[0x168fc+220]=uint8_t(policy^99);m[0x168fc+221]=uint8_t(policy^199);m[0x168fc+79]=uint8_t(policy);m[0x168fc+78]=uint8_t(policy^88);for(unsigned i=0;i<32;++i)m[0x1532e + i]=uint8_t(i*17);m[0x159f2]=m[0x159f3]=255;m[0x167ba]=uint8_t(policy%3);m[0x167d3]=uint8_t(policy);
unsigned count=0;int previous=-1;tracking=true;{T t({0xffa19801});while(!t.complete()){struct Unowned{};check(!t.task<Unowned>(),"Unknown arp task query");const auto cost=t.nextClocks(previous);check(cost>0,"Arp pure stalled");std::array<unsigned char,sizeof(T)>saved{};std::memcpy(saved.data(),&t,sizeof(T));unsigned callbacks=0;check(t.advanceBefore(cost-1,[&](uint32_t,unsigned){++callbacks;return uint8_t(0);},[&](uint32_t,uint8_t,unsigned){++callbacks;},previous)==0&&!callbacks&&!std::memcmp(saved.data(),&t,sizeof(T)),"Arp budget changed object");++rejects;
const auto read=[&](uint32_t a,unsigned dt){check(a<(1u<<24)&&dt<=cost,"Arp pure read bound");++reads;return a==0x400004||a==0x600004?uint8_t(255):m[a];};const auto write=[&](uint32_t a,uint8_t v,unsigned dt){check(a<(1u<<24)&&dt<=cost&&!(a>=0xfff000&&a<0xfffc00),"Arp pure write bound");++writes;m[a]=v;previous=a<0x400000?int(a):-1;};check(t.advanceBefore(cost,read,write,previous)==cost,"Arp pure admission");if(t.effect().write)previous=-1;check(++count<32768,"Arp pure did not complete");++phases;}
const auto&s=t.summary();check(s.part==part,"Arp selected part");check(s.phase==(!held||(policy&8)),"Arp reset phase policy");check(s.mono==(s.phase&&(mode&64)),"Arp mono policy");for(unsigned i=0;i<16;++i)check(!m[base+208+i],"Arp held reset target");check(!m[base+306]&&!m[base+307]&&!m[base+308]&&m[base+314]==255,"Arp reset counters");const bool preserve=!(policy&8)&&(policy&16)&&held;const unsigned last=(mode&1)?0:127,direction=(mode&1)?0:1,octave=(mode&1)?0:policy;check(m[base+322]==(preserve?93:last)&&m[base+323]==(preserve?17:direction)&&m[base+326]==(preserve?99:octave),"Arp directional state oracle");if(s.mono){check(m[base+52]==0&&m[base+53]==1&&m[base+54]==0x90&&m[base+55]==length,"Arp VLQ cursor oracle");uint32_t delta=0;for(unsigned i=0;i<length;++i)delta=(delta<<7)|(policy&127);delta<<=12;check(s.delta==delta&&s.deadline==delta,"Arp VLQ deadline oracle");}struct A{std::array<uint32_t,7>values{};uint8_t flags=0;};A a;projectNativeArpReset(a,t);components|=t.components();}tracking=false;++graphs;}
check(components==511&&!allocations,"Arp pure coverage/heap");std::cout<<"PASS Pure NativeArpReset graphs="<<graphs<<" phases="<<phases<<" whole_object_budget_rejects="<<rejects<<" reads="<<reads<<" writes="<<writes<<" components="<<components<<" sizeof="<<sizeof(T)<<" allocations="<<allocations<<'\n';return 0;
}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
